(()=>{'use strict';const $=id=>document.getElementById(id),canvas=$('battle'),ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=false;
const paths={mageWalk:'assets/characters/loadouts/wand/acolyte/purple/light-walk.png',mageAttack:'assets/characters/loadouts/wand/acolyte/purple/light-attack.png',archerWalk:'assets/characters/loadouts/bow/wanderer/forest/light-walk.png',archerAttack:'assets/characters/loadouts/bow/wanderer/forest/light-attack.png',wolf:'assets/companions/wolf.png'},images={};
const names={mage:'Маг',archer:'Лучник',wolf:'Волк'},labels={normal:'Стрела',fire:'Огонь',ice:'Лёд',piercing:'Пробивная',poison:'Яд',explosive:'Взрывная',barbed:'Зазубренная',bleed:'Кровотечение',wolfBleed:'Раздирающий укус',bite:'Укус',burn:'Ожог',fusion:'Слияние стихий',chaos:'Стихийный хаос',reflection:'Возмездие',evasion:'Уклонение',echo:'Эхо',overload:'Перегрузка',archmage:'Архимаг',dance:'Танец стрел',rain:'Град стрел',rend:'Раздирающий укус',roar:'Рык'};
const colors={fire:'#ffb34b',ice:'#93dfff',normal:'#e4d0a3',piercing:'#fff1bf',poison:'#87d965',explosive:'#ffa54a',barbed:'#e57673',fusion:'#ffe4bd',chaos:'#c8a1ff',burn:'#ff9a47',bite:'#eee5cb',bleed:'#e76d66',wolfBleed:'#e76d66'};
for(const id of ['mageRank','archerRank'])for(let n=0;n<=5;n++){let o=document.createElement('option');o.value=n;o.textContent=n===5?'V · максимум':n===0?'0 · без навыков':String(n);o.selected=n===5;$(id).append(o);}
let duel=null,running=false,swapped=false,last=0,projectiles=[],poses={},numbers=[],ready=false,flash={},state=null;
function options(){return {mageRank:+$('mageRank').value,archerRank:+$('archerRank').value,wolf:$('wolf').checked,seed:+$('seed').value,distance:$('distance').value,talents:$('talents').checked?['revenge','doubleEcho','immortality']:[]};}
function init(start){duel=EmberPvP.createDuel(options());state=duel.getState();running=start;last=0;poses={};projectiles=[];numbers=[];flash={};$('log').replaceChildren();$('outcome').hidden=true;$('start').textContent=start?'Заново':'Начать бой';$('pause').disabled=!start;$('pause').textContent='Пауза';$('notice').textContent=start?'Дуэль · '+(state.talents.length?'3 таланта':'без талантов'):'Нажмите «Начать бой»';render();}
function pos(id){const w=state.units.wolf,near=state.close,m=near?150:88,a=near?330:391;let x=id==='mage'?m:id==='archer'?a:Math.max(m+38,a-(a-m-38)*Math.min(1,state.time/(near?.6:1.1)));if(id==='archer'&&poses.archer?.kind==='evasion')x+=18*Math.sin(Math.PI*Math.min(1,(state.time-poses.archer.at)/.81));return {x:swapped?480-x:x,y:id==='wolf'?223:219};}
function bar(id,v,max){$(id).style.width=(max?Math.max(0,Math.min(100,v/max*100)):0)+'%';}
const num=n=>String(Math.round(n*10)/10).replace('.',',');
function log(e,msg){const d=document.createElement('div');const stamp=document.createElement('span');stamp.textContent=num(e.at)+' с · ';d.append(stamp,document.createTextNode(msg));$('log').append(d);if($('log').children.length>100)$('log').firstElementChild.remove();$('log').scrollTop=$('log').scrollHeight;}
function consume(es){for(const e of es){if(e.type==='launch')projectiles.push(e);if(e.type==='pose')poses[e.source]=e;if(e.type==='skill'){if(e.kind==='evasion')poses.archer={at:e.at,duration:.81,kind:'evasion'};log(e,names[e.source]+' · '+(labels[e.kind]||e.kind));}if(e.type==='hit'){numbers.push({...e,text:e.damage?'-'+Math.round(e.damage):'Блок'});flash[e.target]=e.at;log(e,names[e.source]+' → '+names[e.target]+': '+num(e.damage)+' · '+(labels[e.kind]||e.kind));}if(e.type==='sphere')numbers.push({...e,text:'−'+Math.round(e.absorbed)+' щит',kind:'ice'});if(e.type==='miss'){numbers.push({...e,text:'Промах'});log(e,'Лучник уклонился');}if(e.type==='death')log(e,names[e.target]+' повержен');if(e.type==='revive')log(e,names[e.target]+' возвращается · '+num(e.hp)+' HP');if(e.type==='end'){running=false;$('pause').disabled=true;$('outcome').hidden=false;$('outcome').textContent=e.winner==='draw'?'Ничья':names[e.winner]+' победил';log(e,$('outcome').textContent);}}}
function sprite(id){const u=state.units[id],p=pos(id);if(id==='wolf'&&!state.wolfOn)return;const pose=poses[id],age=pose?state.time-pose.at:Infinity,attack=age>=0&&age<pose?.duration;
ctx.save();if(u.hp<=0)ctx.globalAlpha=.28;ctx.fillStyle='#09130c99';ctx.beginPath();ctx.ellipse(p.x,p.y-1,id==='wolf'?27:19,4,0,0,Math.PI*2);ctx.fill();
if(id==='wolf'){let im=images.wolf;if(im){const right=swapped,y=u.hp<=0?(right?0:192):attack?(right?160:352):state.time<(state.close?.6:1.1)?(right?128:320):(right?56:248),h=y===56||y===248?40:32,frame=u.hp<=0?3:attack?Math.min(4,Math.floor(age*12)):state.time<(state.close?.6:1.1)?Math.floor(state.time*12)%5:0;ctx.drawImage(im,320+64*frame,y,64,h,p.x-48,p.y-h*1.5,96,h*1.5);}}
else{const right=id==='mage'?!swapped:swapped,row=right?3:1,im=images[id+(attack?'Attack':'Walk')],tile=!attack&&id==='archer'?128:64,frames=id==='mage'?6:13,frame=attack?Math.min(frames-1,Math.floor(age/pose.duration*frames)):0;const scale=1.65;if(im)ctx.drawImage(im,frame*tile,row*tile,tile,tile,p.x-tile*scale/2,p.y-(tile/2+27)*scale,tile*scale,tile*scale);}
if(u.hp>0&&id==='mage'&&u.sphere>0){ctx.strokeStyle='#90c9efcc';ctx.fillStyle='#7aaad21b';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(p.x,p.y-32,27,39,0,0,Math.PI*2);ctx.fill();ctx.stroke();}
if(u.hp>0&&u.status){ctx.fillStyle=u.status.kind==='ice'?'#92e0ff88':'#ff993966';ctx.fillRect(p.x-12,p.y-36,24,34);}
ctx.restore();}
function render(){if(!state)return;const u=state.units;bar('mageHp',u.mage.hp,u.mage.maxHp);bar('archerHp',u.archer.hp,u.archer.maxHp);bar('sphereHp',u.mage.sphere,u.mage.sphereMax);bar('wolfHp',u.wolf.hp,u.wolf.maxHp);$('mageText').textContent=num(u.mage.hp)+' / '+num(u.mage.maxHp)+' HP';$('archerText').textContent=num(u.archer.hp)+' / '+num(u.archer.maxHp)+' HP';$('sphereText').textContent='Сфера '+num(u.mage.sphere)+' / '+num(u.mage.sphereMax);$('wolfText').textContent=state.wolfOn?'Волк '+num(u.wolf.hp)+' / '+num(u.wolf.maxHp):'Без волка';$('clock').textContent=state.time.toFixed(2).replace('.',',')+' с';
ctx.clearRect(0,0,480,260);ctx.fillStyle='#13251b38';ctx.fillRect(0,0,480,260);ctx.fillStyle='#22342688';ctx.fillRect(0,224,480,36);for(const id of ['mage','archer','wolf'])sprite(id);
projectiles=projectiles.filter(e=>state.time<=e.impactAt);for(const e of projectiles){const a=pos(e.source),b=pos(e.target),q=Math.max(0,Math.min(1,(state.time-e.at)/(e.impactAt-e.at))),x=a.x+(b.x-a.x)*q,y=a.y-34+(b.y-a.y)*q,dir=Math.sign(b.x-a.x),c=colors[e.kind]||'#e4d0a3';ctx.strokeStyle=c;ctx.fillStyle=c;ctx.lineWidth=2;if(e.source==='mage'){ctx.fillRect(x-4,y-4,8,8);ctx.fillRect(x-12*dir,y-2,12,4);ctx.fillStyle='#fff5d8';ctx.fillRect(x-2,y-2,4,4);}else{ctx.beginPath();ctx.moveTo(x-17*dir,y);ctx.lineTo(x+3*dir,y);ctx.stroke();ctx.beginPath();ctx.moveTo(x+5*dir,y);ctx.lineTo(x-2*dir,y-3);ctx.lineTo(x-2*dir,y+3);ctx.fill();}}
numbers=numbers.filter(e=>state.time-e.at<.85);ctx.font='bold 13px system-ui';ctx.textAlign='center';for(const e of numbers){const p=pos(e.target),a=state.time-e.at;ctx.globalAlpha=Math.max(0,1-a/.85);ctx.lineWidth=3;ctx.strokeStyle='#182419';ctx.fillStyle=colors[e.kind]||'#f4ddab';ctx.strokeText(e.text,p.x,p.y-56-a*28);ctx.fillText(e.text,p.x,p.y-56-a*28);}ctx.globalAlpha=1;}
$('start').disabled=true;Promise.all(Object.entries(paths).map(([k,url])=>new Promise((ok,fail)=>{const im=new Image();im.onload=()=>{images[k]=im;ok();};im.onerror=()=>fail(Error(url));im.src=url;}))).then(()=>{ready=true;$('start').disabled=false;init(false);}).catch(e=>{$('notice').textContent='Не загрузился спрайт: '+e.message;});
$('start').onclick=()=>{if(ready)init(true);};$('pause').onclick=()=>{if(!duel||state.result)return;running=!running;if(running)duel.resume();else duel.pause();$('pause').textContent=running?'Пауза':'Продолжить';last=0;};$('swap').onclick=()=>{swapped=!swapped;render();};$('random').onclick=()=>{if(ready){$('seed').value=Math.floor(Math.random()*4294967296);init(true);}};for(const id of ['mageRank','archerRank','distance','seed','wolf','talents'])$(id).onchange=()=>{if(!running&&!state?.result&&ready)init(false);};
function frame(now){if(running&&duel){if(last){consume(duel.advance(Math.min(.1,(now-last)/1000)*(+$('speed').value)));state=duel.getState();render();}last=now;}requestAnimationFrame(frame);}requestAnimationFrame(frame);
})();